INSERT INTO categories (id, name, slug, description, image_url) VALUES
(1, 'Smartphones', 'smartphones', 'Flagship and value smartphones with powerful cameras and all-day batteries.', 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=900&q=80'),
(2, 'Laptops', 'laptops', 'Ultrabooks, workstations and gaming laptops for work, study and play.', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=900&q=80'),
