(4, 'Audio', 'audio', 'Headphones, earbuds and portable speakers with rich, clear sound.', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=900&q=80'),
(5, 'Wearables', 'wearables', 'Smartwatches that track fitness, sleep and notifications.', 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=900&q=80'),
(6, 'Gaming', 'gaming', 'Consoles, controllers and gear built for competitive play.', 'https://images.unsplash.com/photo-1606144042614-b2417e99c4e3?auto=format&fit=crop&w=900&q=80'),
(7, 'Accessories', 'accessories', 'Mice, keyboards, chargers and power banks for everyday setups.', 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?auto=format&fit=crop&w=900&q=80'),
(8, 'Monitors', 'monitors', 'Colour-accurate and high-refresh displays for desks of every size.', 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=900&q=80');
